const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '一元二次方程：1x² − 3x + 2 = 0' },
      { kind: 'text', payload: '求根公式' },
      { kind: 'text', payload: 'x =' },
      { kind: 'text', payload: '−' },
      { kind: 'text', payload: 'b' },
      { kind: 'text', payload: '±' },
      { kind: 'text', payload: '√(' },
      { kind: 'text', payload: 'b²' },
      { kind: 'text', payload: '− 4' },
      { kind: 'text', payload: 'a' },
      { kind: 'text', payload: 'c' },
      { kind: 'text', payload: ')' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: 'a' },
      { kind: 'text', payload: 'a = 1' },
      { kind: 'text', payload: 'b = −3' },
      { kind: 'text', payload: 'c = 2' },
      { kind: 'text', payload: 'Δ = b² − 4ac = 1' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W / 2;
    var left = Math.max(60, cx - 190);
    var titleY = H * 0.08;
    var subtitleY = H * 0.14;
    var numY = H * 0.28;
    var barY = H * 0.34;
    var denY = H * 0.40;
    var calloutY1 = H * 0.60;
    var calloutY2 = H * 0.70;
    var deltaY = H * 0.86;
    var dark = '#1F2937';
    var blue = '#1D4ED8';
    var orange = '#C2410C';
    var green = '#15803D';
    function label(i, x, y, color, h, v) {
      return {
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: x, y: y },
        hAlign: h || 'center',
        vAlign: v || 'middle',
        color: color
      };
    }
    var fracCommands = [['M', left + 60, barY], ['L', left + 365, barY]];
    var bLead = [
      ['M', left + 100, numY + 12], ['L', left + 100, calloutY2 - 40],
      ['M', left + 100, calloutY2 - 40], ['L', left + 60, calloutY2 - 40],
      ['M', left + 60, calloutY2 - 40], ['L', left + 60, calloutY2 - 14]
    ];
    var aLead = [
      ['M', left + 230, denY + 12], ['L', left + 230, calloutY1 - 40],
      ['M', left + 230, calloutY1 - 40], ['L', left + 180, calloutY1 - 40],
      ['M', left + 180, calloutY1 - 40], ['L', left + 180, calloutY1 - 14]
    ];
    var cLead = [
      ['M', left + 330, numY + 12], ['L', left + 330, calloutY1 - 40],
      ['M', left + 330, calloutY1 - 40], ['L', left + 360, calloutY1 - 40],
      ['M', left + 360, calloutY1 - 40], ['L', left + 360, calloutY1 - 14]
    ];
    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'frac', commands: fracCommands },
        { id: 'bLead', commands: bLead },
        { id: 'aLead', commands: aLead },
        { id: 'cLead', commands: cLead }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'frac', fill: dark, stroke: { width: 3 } },
          { type: 'path', pathId: 'bLead', fill: blue, stroke: { width: 2 } },
          { type: 'path', pathId: 'aLead', fill: orange, stroke: { width: 2 } },
          { type: 'path', pathId: 'cLead', fill: green, stroke: { width: 2 } },
          label(0, cx, titleY, dark),
          label(1, cx, subtitleY, dark),
          label(2, left + 30, numY, dark),
          label(3, left + 75, numY, dark),
          label(4, left + 100, numY, blue),
          label(5, left + 135, numY, dark),
          label(6, left + 170, numY, dark),
          label(7, left + 210, numY, blue),
          label(8, left + 250, numY, dark),
          label(9, left + 300, numY, orange),
          label(10, left + 330, numY, green),
          label(11, left + 355, numY, dark),
          label(12, left + 200, denY, dark),
          label(13, left + 230, denY, orange),
          label(14, left + 180, calloutY1, orange),
          label(15, left + 60, calloutY2, blue),
          label(16, left + 360, calloutY1, green),
          label(17, cx, deltaY, dark)
        ]
      }
    };
  }
};
